WITH exploded AS (SELECT id, plan, currency, element FROM price_tiers LATERAL VIEW EXPLODE(tier_limits) e AS element) SELECT plan, CASE WHEN element >= 83 THEN 'PREMIUM' ELSE 'STANDARD' END AS element_tier, ROUND(AVG(element), 2) AS avg_element, COUNT(*) AS cnt, COUNT(CASE WHEN currency = 'THB' THEN 1 END) AS thb_count, MIN(element) AS min_element, PERCENTILE_APPROX(element, 0.95) AS element_p95, COUNT(DISTINCT id) AS distinct_ids FROM exploded GROUP BY ROLLUP (plan, CASE WHEN element >= 83 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY element_tier ASC NULLS FIRST;
